    gs.palette = palette
    gs.paletteFadeState = {
      startColors: colors.map((color) => [...color] as [number, number, number]),
      targetColors: colors.map((color) => [...color] as [number, number, number]),
      startTimeMs: performance.now(),
      totalMs: 10_000_000,
      mode: 'lerp',
      steps: 1,
      increment: 0,
      remap: { from: DIALOG, to: 0x4e },
