    expect(at(fb, 240, 169)).toBe(SPRITE)

    draw(true)
    expect(gs.wScreenWave).toBe(120)
    expect(gs.sWaveProgression).toBe(-8)
    expect(at(fb, 218, 8)).toBe(WORLD_TILE_COLOR)
    expect(at(fb, 210, 8)).not.toBe(WORLD_TILE_COLOR)
    expect(at(fb, 240, 169)).toBe(SPRITE)
  })
})

